import{z as A,x as d,o as n,c,q as o,j as t,D as i,d as r,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Manacher","description":"","frontmatter":{"title":"Manacher","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/manacher.md","filePath":"cs/manacher.md","lastUpdated":1791063341000}'),p={name:"cs/manacher.md"};function B(h,a,m,C,D,u){const E=d("Mermaid");return n(),c("div",null,[a[2]||(a[2]=o('<h1 id="manacher" tabindex="-1">Manacher <a class="header-anchor" href="#manacher" aria-label="Permalink to &quot;Manacher&quot;">​</a></h1><div class="epigraph"><p>回文半径数组在已覆盖的对称窗口内复制，再尝试延长，线性求出全部最长回文半径。</p><footer>—— 据 Manacher, A New Linear-Time On-Line Algorithm for Finding the Longest Palindromic Substring, 1975 整理</footer></div><p>上一课<a href="/cs/z-function">Z 函数</a>复用与前缀的 LCP 窗口；回文不同，它的约束是中心对称，不是与前缀比。缺口是 Manacher：怎么把已算出的回文在窗口内复用，把朴素扩中心的 \\(O(n^2)\\) 压成 \\(O(n)\\)。不重写 Z-box 定义；后课最小表示法换回旋转串。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素做法枚举约 \\(2n\\) 个中心、逐个向外扩，最坏 \\(O(n^2)\\)。Manacher 第一步统一奇偶：字符间插 <code>#</code>、两端加哨兵，变换串（如 <code>^#a#b#...#$</code>）长 \\(2n+1\\)，回文半径全在字符位上定义，奇偶只剩一种。对每个位置记 \\(p[i]\\)：以 \\(i\\) 为中心的最大回文半径。算法维护右伸最远的回文窗口（中心 \\(c\\)、右界 \\(r\\)）：当 \\(i\\le r\\) 时，对称点 \\(2c-i\\) 已算过，其回文与 \\(i\\) 的回文在窗口内逐位相同，故 \\(p[i]\\) 从 \\(\\min(p[2c-i], r-i)\\) 起步，超出窗口的部分再逐字符比较。</p><p><span class="marginnote">数字实例：<code>ababa</code> 变换为 <code>^#a#b#a#b#a#$</code>，以中间那个 <code>a</code> 为中心的半径算出来是 5，恰好等于原串最长回文 <code>ababa</code> 的长度——分隔符让「变换串半径」与「原串回文长度」一一对应，奇偶两种中心合并成一种。</span></p><p>缺口是对称复制，不是哈希判回文（期望线性）。</p><h3 id="子串不是子序列" tabindex="-1">子串不是子序列 <a class="header-anchor" href="#子串不是子序列" aria-label="Permalink to &quot;子串不是子序列&quot;">​</a></h3><p>本课对象是连续子串；回文子序列是另一套区间 DP。也不要拿「原串与反串的 LCS」当主算法——那同样 \\(O(n^2)\\)，Manacher 是确定性的线性。</p><p><span class="marginnote"> Manacher 1975。后课最小表示是旋转，不是回文。回文树（eertree）点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程：先变换串；从左到右扫 \\(i\\)，落在窗口内先取对称点给的下界，再向两边尝试扩，扩成功就更新 \\(c,r\\)，窗口始终保持最靠右。结束取 \\(\\max p[i]\\) 为最长回文长度，原串起点是 \\((i-p[i])/2\\)——分隔符使下标换算多一步，忘掉换算是最常见的错法。</p>',12)),(n(),t(s,null,{default:i(()=>[l(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%8F%92%20%23%20%E7%BB%9F%E4%B8%80%E5%A5%87%E5%BF%83%22%5D%20--%3E%20C%5B%22%E4%B8%AD%E5%BF%83%20c%2C%20%E5%8F%B3%E7%95%8C%20r%22%5D%0A%20%20C%20--%3E%20P%5B%22%E5%8D%8A%E5%BE%84%20p%5Bi%5D%22%5D%0A%20%20P%20--%3E%20PAL%5B%22%E5%85%A8%E9%83%A8%E5%9B%9E%E6%96%87%E5%AD%90%E4%B8%B2%E5%8D%8A%E5%BE%84%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不同回文子串的计数不能拿 \\(p\\) 直接求和（要区分来自原串字符与分隔符的回文），在本课结论上再处理，本课只点名。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},[r("常见误区：初学者最容易栽在换算上——\\(p[i]\\) 是变换串里的半径，输出却要原串下标：长度直接取 \\(p[i]\\)，起点要按分隔符偏移折半。建议拿奇数长 "),e("code",null,"ababa"),r(" 与偶数长 "),e("code",null,"abba"),r(" 各测一遍，两种中心都对上才敢交。")])],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"正确性系于一条对称性：大回文关于 \\(c\\) 镜像，窗口内的 \\(i\\) 与镜像点 \\(2c-i\\) 的回文逐位相同。镜像回文完全落在窗口内时，\\(p[i]\\) 直接抄 \\(p[2c-i]\\)，一次比较都不花；镜像回文顶到窗口右界时，只能保证 \\(r-i\\)，再往外必须逐字符验证——窗口外没有对称信息可抄。均摊记账：每次比较成功都让 \\(r\\) 前进，\\(r\\) 至多走 \\(O(n)\\) 步，失败比较随即并入 \\(p[i]\\) 终止，总时间线性。与 Z 函数同构的正是这套「窗口内复用、越界才扩」的记账；KMP 的失败指针是另一套结构，无直接公式。",-1)),(n(),t(s,null,{default:i(()=>[l(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E5%A4%84%E7%90%86%E4%BD%8D%E7%BD%AE%20i%22%5D%20--%3E%20IN%7B%22i%20%E5%9C%A8%E7%AA%97%E5%8F%A3%20c..r%20%E5%86%85%3F%22%7D%0A%20%20IN%20--%3E%7C%22%E5%90%A6%22%7C%20ZERO%5B%22p%5Bi%5D%20%E4%BB%8E%200%20%E8%B5%B7%E6%AD%A5%22%5D%0A%20%20IN%20--%3E%7C%22%E6%98%AF%22%7C%20MIR%5B%22%E6%9F%A5%E9%95%9C%E5%83%8F%E7%82%B9%202c-i%22%5D%0A%20%20MIR%20--%3E%20CASE%7B%22%E9%95%9C%E5%83%8F%E5%9B%9E%E6%96%87%E5%AE%8C%E5%85%A8%E5%9C%A8%E7%AA%97%E5%8F%A3%E5%86%85%3F%22%7D%0A%20%20CASE%20--%3E%7C%22%E6%98%AF%22%7C%20COPY%5B%22%E7%9B%B4%E6%8E%A5%E6%8A%84%20p%5B2c-i%5D%2C%20%E4%B8%80%E6%AC%A1%E6%AF%94%E8%BE%83%E4%B8%8D%E8%8A%B1%22%5D%0A%20%20CASE%20--%3E%7C%22%E5%90%A6%22%7C%20MIN%5B%22%E4%BB%8E%20r-i%20%E8%B5%B7%E6%AD%A5%2C%20%E8%B6%8A%E7%95%8C%E9%83%A8%E5%88%86%E9%80%90%E5%AD%97%E7%AC%A6%E6%89%A9%22%5D%0A%20%20COPY%20--%3E%20ADV%5B%22i%20%E5%8F%B3%E7%A7%BB%E4%B8%80%E6%A0%BC%22%5D%0A%20%20MIN%20--%3E%20ADV%0A%20%20ZERO%20--%3E%20ADV%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">直觉类比：右界 \\(r\\) 像铺地板铺到的最远处，每次成功的比较都多铺一块；镜像点给的则是「看过的图纸」，窗内照抄、不必重铺。铺设总量封顶 \\(n\\)，所以整体线性——这就是均摊：个别位置多花几下，总账有人兜底。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写回文树（eertree），不写二维回文。后课默认：最长回文子串用线性 Manacher。下一课循环串最小表示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>半径数组 + 对称窗口 = \\(O(n)\\)。</li><li>连续回文子串，不是子序列。</li><li>分隔符统一奇偶中心。</li><li>出处：Manacher, 1975。</li></ul>',5))])}const P=A(p,[["render",B]]);export{f as __pageData,P as default};
